import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, sampler } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
  };

  // Atlas region: 512×320 pixels → aspect 1.6:1
  const aspectRatio = 512 / 320;
  const planeWidth = 1.6;
  const planeHeight = 1.0;

  // Create plane geometry
  const planeGeometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // Load ceramic grain texture
  let diffuseTexture = null;
  if (config.imageUrl) {
    diffuseTexture = await ctx.textureLoader.loadTexture(config.imageUrl);
    diffuseTexture.colorSpace = 'srgb';
  }

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial();

  if (diffuseTexture) {
    // TSL node setup: sample from atlas region [0,0] to [512,320]
    // Atlas region as normalized UV: x ∈ [0, 512/atlasWidth], y ∈ [0, 320/atlasHeight]
    // Assuming standard atlas layout, use direct UV for this region
    const sampledColor = sampler(diffuseTexture, uv());
    material.colorNode = sampledColor;
  } else {
    // Fallback to engineered surface: ink-to-paper gradient + grain texture
    const normalizedUv = uv();
    const gradient = mix(
      vec3(0x16 / 255, 0x16 / 255, 0x1d / 255), // ink
      vec3(0xe8 / 255, 0xec / 255, 0xf2 / 255), // paper
      smoothstep(0, 1, normalizedUv.y)
    );
    material.colorNode = gradient;
  }

  material.side = ctx.THREE.DoubleSide;
  material.transparent = true;

  const plane = new Mesh(planeGeometry, material);
  plane.position.z = 0;

  group.add(plane);

  return group;
}
